import {
  drawArrow,
  drawLabel,
  drawMatrixBlock,
  drawStepBox,
  Sel,
} from '../primitives';
import { ComputationGraph } from '../../graph/types';
import { ComponentDef } from '../../components/types';
import { StepInfo } from './index';

export interface StepConfig {
  label: string;
  formula?: string;
  fill?: string;
  stroke?: string;
  explanation?: string;
  code?: { title: string; lines: string[] };
  matrices?: Array<{
    label: string;
    sublabel?: string;
    fill?: string;
    stroke?: string;
    w?: number;
    h?: number;
  }>;
  tensorGrid?: {
    rows: number;
    cols: number;
    label?: string;
  };
}

export interface ExplanationConfig {
  text: string;
  type: 'insight' | 'math' | 'perf' | 'warning';
}

export interface CodeConfig {
  title: string;
  desc?: string[];
  lines: string[];
}

export interface ComponentRenderConfig {
  title: string;
  paramSummary?: string;
  inputTensor: string;
  outputTensor: string;
  steps: StepConfig[];
  explanations: ExplanationConfig[];
  paramCount?: string;
  flops?: string;
  code: CodeConfig;
}

const STEP_COLORS = ['#16a34a', '#1976d2', '#7b1fa2', '#d97706', '#d32f2f', '#00838f', '#db2777', '#0284c7'];
const STEP_FILLS  = ['#dcfce7', '#dbeafe', '#ede9fe', '#fef3c7', '#fee2e2', '#ccfbf1', '#fce7f3', '#e0f2fe'];

// ─────────────────────────────────────────────────────────────────────────────
// SVG renderer (centre column)
// ─────────────────────────────────────────────────────────────────────────────

export function renderFromConfig(
  config: ComponentRenderConfig,
  g: Sel,
  _params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const totalW = 560;
  const cx = totalW / 2;
  let y = 30;

  // Title
  drawLabel(g, cx, y, config.title, { size: 14, weight: '700', color: 'var(--text)' });
  y += 18;
  if (config.paramSummary) {
    drawLabel(g, cx, y, config.paramSummary, { size: 9, color: 'var(--text-muted)' });
    y += 22;
  }
  y += 8;

  // Input tensor
  drawTensorBox(g, cx - 120, y, 240, 32, config.inputTensor, '#16a34a');
  y += 50;

  // Steps
  config.steps.forEach((step, i) => {
    const color  = step.stroke || STEP_COLORS[i % STEP_COLORS.length];
    const fill   = step.fill   || STEP_FILLS[i % STEP_FILLS.length];

    drawArrow(g, cx, y - 18, cx, y - 2, { color: '#94a3b8' });

    // Step box — tag with class for highlight
    const grp = (g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>)
      .append('g')
      .attr('class', `step-node step-cfg-${i + 1}`)
      .attr('data-step', String(i + 1));

    drawStepBox(grp as unknown as Sel, cx - 130, 0, 260, 44, step.label, {
      step: i + 1,
      fill,
      stroke: color,
      formula: step.formula,
    });

    // Translate the group to current y
    grp.attr('transform', `translate(0, ${y})`);

    y += 56;

    // Weight matrices
    if (step.matrices && step.matrices.length > 0) {
      const gap = 10;
      const widths  = step.matrices.map(m => m.w || 70);
      const heights = step.matrices.map(m => m.h || 50);
      const totalMW = widths.reduce((a, b) => a + b, 0) + (widths.length - 1) * gap;
      let mx = cx - totalMW / 2;

      const matGrp = (g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>)
        .append('g')
        .attr('class', `step-node step-cfg-${i + 1}`)
        .attr('data-step', String(i + 1));

      step.matrices.forEach((m, mi) => {
        drawMatrixBlock(matGrp as unknown as Sel, mx, y, {
          width:    widths[mi],
          height:   heights[mi],
          label:    m.label,
          sublabel: m.sublabel,
          fill:     m.fill   || fill,
          stroke:   m.stroke || color,
        });
        mx += widths[mi] + gap;
      });
      y += Math.max(...heights) + 16;
    }
  });

  drawArrow(g, cx, y - 18, cx, y - 2, { color: '#94a3b8' });
  drawTensorBox(g, cx - 120, y, 240, 32, config.outputTensor, '#16a34a');
  y += 50;

  if (config.paramCount || config.flops) {
    const parts: string[] = [];
    if (config.paramCount) parts.push(`Params: ${config.paramCount}`);
    if (config.flops)      parts.push(`FLOPs: ${config.flops}`);
    drawLabel(g, cx, y, parts.join('    '), { size: 10, color: '#1976d2', weight: '600' });
    y += 24;
  }

  const steps = buildStepInfos(config);
  return { width: totalW, height: y + 20, steps };
}

// ─────────────────────────────────────────────────────────────────────────────
// Convert StepConfig[] + explanations + code → StepInfo[]
// Each step gets: its own explanation text (if provided) + shared code block
// The last "step" also collects the overall explanations
// ─────────────────────────────────────────────────────────────────────────────

function buildStepInfos(config: ComponentRenderConfig): StepInfo[] {
  const { steps, explanations, code } = config;

  return steps.map((step, i): StepInfo => {
    const color = step.stroke || STEP_COLORS[i % STEP_COLORS.length];
    const fill  = step.fill   || STEP_FILLS[i % STEP_FILLS.length];

    // Build explanation text for this step
    const parts: string[] = [];
    if (step.explanation) {
      parts.push(step.explanation);
    }
    // Distribute global explanations evenly across steps
    const expPerStep = Math.ceil(explanations.length / steps.length);
    const expStart   = i * expPerStep;
    const expSlice   = explanations.slice(expStart, expStart + expPerStep);
    expSlice.forEach(e => parts.push(e.text));

    const explanation = parts.join('\n\n') ||
      `${step.label}${step.formula ? ` — ${step.formula}` : ''}`;

    // Step-specific code if provided, else fall back to shared code
    const stepCode = step.code ?? {
      title: code.title,
      lines: code.lines,
    };

    return {
      id:         i + 1,
      label:      step.label,
      shortLabel: step.label.length > 28 ? step.label.slice(0, 26) + '…' : step.label,
      formula:    step.formula ?? '',
      explanation,
      code:       stepCode,
      svgGroup:   `step-cfg-${i + 1}`,
      color,
      fill,
    };
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Tensor box (dashed border, like input/output)
// ─────────────────────────────────────────────────────────────────────────────

function drawTensorBox(g: Sel, x: number, y: number, w: number, h: number, label: string, color: string): void {
  const grp = (g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>)
    .append('g').attr('transform', `translate(${x},${y})`);
  grp.append('rect')
    .attr('width', w).attr('height', h).attr('rx', 8)
    .attr('fill', 'var(--surface)')
    .attr('stroke', color).attr('stroke-width', 2)
    .attr('stroke-dasharray', '6,3');
  drawLabel(grp as unknown as Sel, w / 2, h / 2, label, {
    size: 10, weight: '600', color: 'var(--text)', font: 'monospace',
  });
}

// Need d3 import for group manipulation
import * as d3 from 'd3';
